CREATE TABLE IF NOT EXISTS users (username VARCHAR(80) COLLATE utf8mb4_bin PRIMARY KEY, password VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rides (id BIGINT AUTO_INCREMENT PRIMARY KEY, driver VARCHAR(80) COLLATE utf8mb4_bin NOT NULL, origin VARCHAR(100) NOT NULL, destination VARCHAR(100) NOT NULL, departure TIMESTAMP NOT NULL, price DECIMAL(10,2) NOT NULL CHECK(price>0), seats INT NOT NULL CHECK(seats BETWEEN 0 AND 6), car VARCHAR(100) NOT NULL, FOREIGN KEY(driver) REFERENCES users(username)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) COLLATE utf8mb4_bin NOT NULL, ride_id BIGINT NOT NULL, UNIQUE(username,ride_id), FOREIGN KEY(username) REFERENCES users(username), FOREIGN KEY(ride_id) REFERENCES rides(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
